    return int(round(float(xs.mean()))), int(round(float(ys.mean())))


def control_action(frame):
    controls = [
        blob
        for blob in connected_components(frame, colors=(8,), min_area=3)
        if blob.bbox[1] <= 5 and blob.bbox[0] < 63
    ]
