AMBIGUOUS = (19, 21, 22, 23, 41)


def advance(node, actions):
    height = 0
    for action in actions:
        if node.terminal():
            break
        before = arr(node.frame()).copy()
        node.step(*action)
        if not node.terminal():
            height += band_shift(before, node.frame())
    return height


def probe(env):
    with open("checkpoint.json") as stream:
        checkpoint = json.load(stream)
    for action in checkpoint["final_path"]:
        env.step(action)
    with open("frontier_scaffold.json") as stream:
        raw_route = json.load(stream)["staged_prefix_actions"]

    outcomes = []
    for shifted_late in itertools.product((False, True), repeat=len(AMBIGUOUS)):
        shifted_steps = EARLY_SHIFTED | {
            step
            for step, shifted in zip(AMBIGUOUS, shifted_late)
            if shifted
        }
        route = []
        for step, item in enumerate(raw_route, 1):
            action = (item,) if isinstance(item, int) else tuple(item)
            if (
                step in shifted_steps
                and len(action) == 3
                and action[1] != 3
            ):
                action = (action[0], action[1] + 12, action[2])
            route.append(action)

        node = env.clone()
        height = advance(node, [*route, (3,), (3,), (3,), (3,)])
        if node.levels_completed > 6:
            print("WIN_BEFORE_SWITCH", shifted_late, route, flush=True)
            return
        if node.terminal():
