                    [*route, (3,), (3,), (3,), (3,), (6, 3, y)],
                    flush=True,
                )
                return
        outcomes.append(
            (
                True, height, shifted_late, avatar_cell(node.frame()),
                tuple(controls(node.frame())),
            )
        )
    outcomes.sort(
        key=lambda item: (-item[0], -item[1], -len(item[4]), item[2])
    )
    print("NO_DECODE_WIN", len(outcomes))
    for outcome in outcomes:
        print("DECODE", outcome)


